 '办公设备':['增值税电子普通发票_京东_显示器.pdf'],
 '交通出行':['滴滴出行电子发票_10月.pdf'],
 '餐饮':['餐饮发票_2026-09-12.pdf']
}
plan=[(root/name,archive/category/name) for category,names in groups.items() for name in names]
for src,dst in plan:
